    /// <summary>
    /// Write the record
    /// </summary>
    public void write()
    {
        METSalesLine metSalesLine = this.cursor();

        if (metSalesLine.SalesLine)
        {
            next Write();
        }
    }

    /// <summary>
    /// Validate the record
    /// </summary>
    /// <returns>Result of the validation</returns>
    public boolean validatewrite()
    {
        boolean ret = true;
        
        METSalesLine metSalesLine = this.cursor();

        if (metSalesLine.SalesLine)
        {
        
            ret = next validatewrite();
        }

        return ret;
    }

   /// <summary>
   /// This method used for enable/disable controls.
   /// </summary>
   /// <param name="sender">FormDataSource</param>
   /// <param name="e">FormDataSourceEventArgs</param>
   [FormDataSourceEventHandler(formDataSourceStr(ReturnTable, METSalesLine), FormDataSourceEventType::Activated)]
   public static void METSalesLine_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
   {
       FormRun formRun = sender.formRun();

       FormTabPageControl   exciseDutyTab  = formRun.design().controlName(formControlStr(ReturnTable, TabLineExciseDuty));

       exciseDutyTab.visible(METCustParameters::Find().ReturnExciseDutyUpdate);
   }
